-- CloudBase PostgreSQL staging only. auth.uid() and auth.users.id are text.
begin;
create schema if not exists app_private;
revoke all on schema app_private from public;
grant usage on schema app_private to anon, authenticated;
create function app_private.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create table public.profiles (id varchar(64) primary key, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), display_name text not null default '岛屿来客' check(length(display_name) between 1 and 80), bio text not null default '' check(length(bio)<=1000), avatar_path text, status text not null default 'active' check(status in ('active','suspended','deleted')), deleted_at timestamptz);
alter table public.profiles enable row level security;
create trigger touch_updated before update on public.profiles for each row execute function app_private.touch_updated_at();
create table public.communities (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), slug text not null unique, legacy_key text unique, name text not null check(length(name) between 1 and 100), description text not null default '', owner_id varchar(64) references public.profiles(id) on delete set null, visibility text not null default 'public' check(visibility in ('public','private')), status text not null default 'active' check(status in ('active','archived')), deleted_at timestamptz);
alter table public.communities enable row level security;
create trigger touch_updated before update on public.communities for each row execute function app_private.touch_updated_at();
create table public.community_members (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), community_id uuid not null references public.communities(id) on delete cascade, user_id varchar(64) not null references public.profiles(id) on delete cascade, status text not null default 'active' check(status in ('active','left')), unique(community_id,user_id));
alter table public.community_members enable row level security;
create trigger touch_updated before update on public.community_members for each row execute function app_private.touch_updated_at();
create table public.posts (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), author_id varchar(64) not null references public.profiles(id) on delete cascade, community_id uuid references public.communities(id) on delete set null, title text not null check(length(title) between 1 and 200), content text not null check(length(content) between 1 and 20000), status text not null default 'draft' check(status in ('draft','published','hidden','removed')), is_demo boolean not null default false, deleted_at timestamptz);
alter table public.posts enable row level security;
create trigger touch_updated before update on public.posts for each row execute function app_private.touch_updated_at();
create table public.comments (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), post_id uuid not null references public.posts(id) on delete cascade, author_id varchar(64) not null references public.profiles(id) on delete cascade, parent_id uuid references public.comments(id) on delete cascade, content text not null check(length(content) between 1 and 4000), status text not null default 'published' check(status in ('published','hidden','removed')), deleted_at timestamptz);
alter table public.comments enable row level security;
create trigger touch_updated before update on public.comments for each row execute function app_private.touch_updated_at();
create table public.bookmarks (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, unique(user_id,post_id));
alter table public.bookmarks enable row level security;
create trigger touch_updated before update on public.bookmarks for each row execute function app_private.touch_updated_at();
create table public.reactions (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, kind text not null check(kind in ('like','support','helpful')), unique(user_id,post_id,kind));
alter table public.reactions enable row level security;
create trigger touch_updated before update on public.reactions for each row execute function app_private.touch_updated_at();
create table public.hobby_wall_items (id text primary key, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null, category text not null, asset_path text not null check(asset_path like '/pegboard/items/%'), width numeric not null check(width>0), height numeric not null check(height>0), aspect_ratio numeric not null check(aspect_ratio>0), size_class text not null check(size_class in ('XS','S','M','L','XL')), mount_type text not null check(mount_type in ('hook','shelf','clip','frame','holder')), anchor_point jsonb not null, collision_bounds jsonb not null, status text not null default 'active' check(status in ('active','retired')));
alter table public.hobby_wall_items enable row level security;
create trigger touch_updated before update on public.hobby_wall_items for each row execute function app_private.touch_updated_at();
create table public.user_hobby_wall (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, item_id text not null references public.hobby_wall_items(id) on delete restrict, slot smallint not null check(slot between 1 and 5), x numeric not null check(x between 0 and 960), y numeric not null check(y between 0 and 640), rotation numeric not null default 0 check(rotation=0), scale numeric not null default 1 check(scale between 0.3 and 3 and abs(scale*20-round(scale*20))<0.00001), mount_type text not null check(mount_type in ('hook','shelf','clip','frame','holder')), layout_version integer not null default 3 check(layout_version=3), unique(user_id,slot), unique(user_id,item_id));
alter table public.user_hobby_wall enable row level security;
create trigger touch_updated before update on public.user_hobby_wall for each row execute function app_private.touch_updated_at();
create table public.women_profiles (id text primary key, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), slug text not null unique, name_zh text not null, name_en text not null, status text not null check(status in ('candidate','researching','verified','published')), source_data jsonb not null check(jsonb_typeof(source_data)='object'), deleted_at timestamptz);
alter table public.women_profiles enable row level security;
create trigger touch_updated before update on public.women_profiles for each row execute function app_private.touch_updated_at();
create table public.ai_conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, mode text not null check(mode in ('Companion','Explore','Write')), title text not null default '' check(length(title)<=200), deleted_at timestamptz);
alter table public.ai_conversations enable row level security;
create trigger touch_updated before update on public.ai_conversations for each row execute function app_private.touch_updated_at();
create table public.ai_messages (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), conversation_id uuid not null references public.ai_conversations(id) on delete cascade, role text not null check(role in ('user','assistant','system')), content text not null check(length(content) between 1 and 16000), deleted_at timestamptz);
alter table public.ai_messages enable row level security;
create trigger touch_updated before update on public.ai_messages for each row execute function app_private.touch_updated_at();
create table public.reports (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), reporter_id varchar(64) references public.profiles(id) on delete set null, target_type text not null check(target_type in ('post','comment','user')), target_id text not null, reason text not null check(length(reason) between 1 and 2000), status text not null default 'pending' check(status in ('pending','reviewed','dismissed','resolved')));
alter table public.reports enable row level security;
create trigger touch_updated before update on public.reports for each row execute function app_private.touch_updated_at();
create table public.moderation_actions (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), moderator_id varchar(64) references public.profiles(id) on delete set null, report_id uuid references public.reports(id) on delete set null, target_type text not null, target_id text not null, action text not null check(action in ('warn','hide','restore','suspend','delete')), reason text not null check(length(reason)>0));
alter table public.moderation_actions enable row level security;
create trigger touch_updated before update on public.moderation_actions for each row execute function app_private.touch_updated_at();
create table public.notifications (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, kind text not null, payload jsonb not null default '{}'::jsonb, read_at timestamptz, deleted_at timestamptz);
alter table public.notifications enable row level security;
create trigger touch_updated before update on public.notifications for each row execute function app_private.touch_updated_at();
create table public.user_blocks (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, blocked_user_id varchar(64) not null references public.profiles(id) on delete cascade, check(user_id<>blocked_user_id), unique(user_id,blocked_user_id));
alter table public.user_blocks enable row level security;
create trigger touch_updated before update on public.user_blocks for each row execute function app_private.touch_updated_at();
create table public.audit_logs (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), actor_id varchar(64) references public.profiles(id) on delete set null, event text not null, target_type text, target_id text, metadata jsonb not null default '{}'::jsonb);
alter table public.audit_logs enable row level security;
create trigger touch_updated before update on public.audit_logs for each row execute function app_private.touch_updated_at();
create table public.user_consents (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, purpose text not null check(purpose in ('terms','privacy','ai','analytics')), version text not null check(length(version) between 1 and 80), granted boolean not null, unique(user_id,purpose,version));
alter table public.user_consents enable row level security;
create trigger touch_updated before update on public.user_consents for each row execute function app_private.touch_updated_at();
create table public.account_deletion_requests (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, status text not null default 'pending' check(status in ('pending','processing','completed','cancelled')), completed_at timestamptz);
alter table public.account_deletion_requests enable row level security;
create trigger touch_updated before update on public.account_deletion_requests for each row execute function app_private.touch_updated_at();
create table public.import_receipts (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id varchar(64) not null references public.profiles(id) on delete cascade, source_hash text not null, scope text not null check(scope in ('hobby_wall','demo_posts')), unique(user_id,source_hash,scope));
alter table public.import_receipts enable row level security;
create trigger touch_updated before update on public.import_receipts for each row execute function app_private.touch_updated_at();

