revoke all on public.communities from anon,authenticated;
revoke all on public.community_members from anon,authenticated;
revoke all on public.posts from anon,authenticated;
revoke all on public.comments from anon,authenticated;
revoke all on public.bookmarks from anon,authenticated;
revoke all on public.reactions from anon,authenticated;
revoke all on public.hobby_wall_items from anon,authenticated;
revoke all on public.user_hobby_wall from anon,authenticated;
revoke all on public.women_profiles from anon,authenticated;
revoke all on public.ai_conversations from anon,authenticated;
revoke all on public.ai_messages from anon,authenticated;
revoke all on public.reports from anon,authenticated;
revoke all on public.moderation_actions from anon,authenticated;
revoke all on public.notifications from anon,authenticated;
revoke all on public.user_blocks from anon,authenticated;
revoke all on public.audit_logs from anon,authenticated;
revoke all on public.user_consents from anon,authenticated;
revoke all on public.account_deletion_requests from anon,authenticated;
revoke all on public.import_receipts from anon,authenticated;
grant select on public.profiles,public.communities,public.posts,public.comments,public.hobby_wall_items,public.women_profiles to anon,authenticated;
grant select on public.community_members,public.bookmarks,public.reactions,public.user_hobby_wall,public.ai_conversations,public.ai_messages,public.reports,public.notifications,public.user_blocks,public.user_consents,public.account_deletion_requests,public.import_receipts to authenticated;
grant insert on public.community_members,public.posts,public.comments,public.bookmarks,public.reactions,public.user_hobby_wall,public.ai_conversations,public.ai_messages,public.reports,public.user_blocks,public.user_consents,public.account_deletion_requests to authenticated;
grant delete on public.community_members,public.bookmarks,public.reactions,public.user_hobby_wall,public.ai_conversations,public.user_blocks to authenticated;
grant update(display_name,bio,avatar_path) on public.profiles to authenticated;
grant update(title,content,status,deleted_at) on public.posts to authenticated;
grant update(content,deleted_at) on public.comments to authenticated;
grant update(x,y,scale,rotation,mount_type,slot,layout_version) on public.user_hobby_wall to authenticated;
grant update(title,deleted_at) on public.ai_conversations to authenticated;
grant update(read_at) on public.notifications to authenticated;
grant update(granted) on public.user_consents to authenticated;
-- Moderator privileges never come from user metadata or editable profiles.
create table app_private.admins(user_id varchar(64) primary key references public.profiles(id) on delete cascade);
alter table app_private.admins enable row level security;
revoke all on app_private.admins from public,anon,authenticated;
create function app_private.can_read_community(cid uuid) returns boolean language sql stable security definer set search_path='' as $$
 select cid is null or exists(select 1 from public.communities c where c.id=cid and c.deleted_at is null and c.status='active' and (c.visibility='public' or exists(select 1 from public.community_members m where m.community_id=c.id and m.user_id=auth.uid() and m.status='active')))
$$;
create function app_private.not_blocked(uid text) returns boolean language sql stable security definer set search_path='' as $$ select not exists(select 1 from public.user_blocks b where (b.user_id=auth.uid() and b.blocked_user_id=uid) or (b.user_id=uid and b.blocked_user_id=auth.uid())) $$;
create function app_private.can_read_post(pid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.posts p where p.id=pid and p.deleted_at is null and (p.author_id=auth.uid() or (p.status='published' and app_private.can_read_community(p.community_id) and app_private.not_blocked(p.author_id)))) $$;
create function app_private.owns_conversation(cid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.ai_conversations c where c.id=cid and c.user_id=auth.uid() and c.deleted_at is null) $$;
revoke all on all functions in schema app_private from public;
grant execute on function app_private.can_read_community(uuid),app_private.can_read_post(uuid),app_private.not_blocked(text) to anon,authenticated;
grant execute on function app_private.owns_conversation(uuid) to authenticated;
create function app_private.active_user() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and status='active' and deleted_at is null) $$;
revoke all on function app_private.active_user() from public;
grant execute on function app_private.active_user() to authenticated;
create policy public_profiles on public.profiles for select using(status='active' and deleted_at is null or id=auth.uid());
create policy own_profile_edit on public.profiles for update to authenticated using(id=auth.uid() and status='active') with check(app_private.active_user() and id=auth.uid());
create policy readable_communities on public.communities for select using(app_private.can_read_community(id));
create policy own_memberships on public.community_members for select to authenticated using(user_id=auth.uid());
create policy join_public on public.community_members for insert to authenticated with check(app_private.active_user() and user_id=auth.uid() and status='active' and exists(select 1 from public.communities c where c.id=community_id and c.visibility='public' and c.status='active'));
create policy leave_own on public.community_members for delete to authenticated using(user_id=auth.uid());
create policy readable_posts on public.posts for select using(deleted_at is null and (author_id=auth.uid() or (status='published' and app_private.can_read_community(community_id) and app_private.not_blocked(author_id))));
create policy create_own_post on public.posts for insert to authenticated with check(app_private.active_user() and author_id=auth.uid() and status in ('draft','published') and not is_demo and (community_id is null or exists(select 1 from public.community_members m where m.community_id=posts.community_id and m.user_id=auth.uid() and m.status='active')));
create policy edit_own_post on public.posts for update to authenticated using(author_id=auth.uid() and status in ('draft','published')) with check(app_private.active_user() and author_id=auth.uid() and status in ('draft','published'));
create policy readable_comments on public.comments for select using(status='published' and deleted_at is null and app_private.can_read_post(post_id) and app_private.not_blocked(author_id));
create policy create_comment on public.comments for insert to authenticated with check(app_private.active_user() and author_id=auth.uid() and status='published' and app_private.can_read_post(post_id));
create policy edit_comment on public.comments for update to authenticated using(author_id=auth.uid() and status='published') with check(app_private.active_user() and author_id=auth.uid() and app_private.can_read_post(post_id));
create policy active_assets on public.hobby_wall_items for select using(status='active');
create policy published_women on public.women_profiles for select using(status='published' and deleted_at is null);
create policy own_messages_read on public.ai_messages for select to authenticated using(app_private.owns_conversation(conversation_id));
create policy own_user_messages_insert on public.ai_messages for insert to authenticated with check(app_private.active_user() and role='user' and app_private.owns_conversation(conversation_id));
create policy own_reports_read on public.reports for select to authenticated using(reporter_id=auth.uid());
create policy own_reports_insert on public.reports for insert to authenticated with check(app_private.active_user() and reporter_id=auth.uid() and status='pending');
create policy own_notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy own_notifications_seen on public.notifications for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid());
create policy own_deletions_read on public.account_deletion_requests for select to authenticated using(user_id=auth.uid());
create policy own_deletions_request on public.account_deletion_requests for insert to authenticated with check(app_private.active_user() and user_id=auth.uid() and status='pending' and completed_at is null);
create unique index one_pending_deletion on public.account_deletion_requests(user_id) where status in ('pending','processing');
create policy own_import_receipts on public.import_receipts for select to authenticated using(user_id=auth.uid());
create policy own_select on public.bookmarks for select to authenticated using(user_id=auth.uid());
create policy own_insert on public.bookmarks for insert to authenticated with check(app_private.active_user() and user_id=auth.uid() and app_private.can_read_post(post_id));
create policy own_update on public.bookmarks for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid() and app_private.can_read_post(post_id));
create policy own_delete on public.bookmarks for delete to authenticated using(user_id=auth.uid());
create policy own_select on public.reactions for select to authenticated using(user_id=auth.uid());
create policy own_insert on public.reactions for insert to authenticated with check(app_private.active_user() and user_id=auth.uid() and app_private.can_read_post(post_id));
create policy own_update on public.reactions for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid() and app_private.can_read_post(post_id));
create policy own_delete on public.reactions for delete to authenticated using(user_id=auth.uid());
create policy own_select on public.user_hobby_wall for select to authenticated using(user_id=auth.uid());
create policy own_insert on public.user_hobby_wall for insert to authenticated with check(app_private.active_user() and user_id=auth.uid());
create policy own_update on public.user_hobby_wall for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid());
create policy own_delete on public.user_hobby_wall for delete to authenticated using(user_id=auth.uid());
create policy own_select on public.ai_conversations for select to authenticated using(user_id=auth.uid());
create policy own_insert on public.ai_conversations for insert to authenticated with check(app_private.active_user() and user_id=auth.uid());
create policy own_update on public.ai_conversations for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid());
create policy own_delete on public.ai_conversations for delete to authenticated using(user_id=auth.uid());
create policy own_select on public.user_blocks for select to authenticated using(user_id=auth.uid());
create policy own_insert on public.user_blocks for insert to authenticated with check(app_private.active_user() and user_id=auth.uid());
create policy own_update on public.user_blocks for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid());
create policy own_delete on public.user_blocks for delete to authenticated using(user_id=auth.uid());
create policy own_select on public.user_consents for select to authenticated using(user_id=auth.uid());
create policy own_insert on public.user_consents for insert to authenticated with check(app_private.active_user() and user_id=auth.uid());
create policy own_update on public.user_consents for update to authenticated using(user_id=auth.uid()) with check(app_private.active_user() and user_id=auth.uid());
create policy own_delete on public.user_consents for delete to authenticated using(user_id=auth.uid());
