-- Five slots + UNIQUE(user_id,slot) enforce a hard transactional maximum, even with concurrent REST inserts.
create function app_private.validate_wall() returns trigger language plpgsql security definer set search_path='' as $$
 declare asset public.hobby_wall_items; b jsonb; other public.user_hobby_wall; ob jsonb; l numeric; t numeric; w numeric; h numeric;
 begin
 perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,0));
 select * into asset from public.hobby_wall_items where id=new.item_id and status='active';
 if not found or new.mount_type<>asset.mount_type then raise exception 'invalid wall asset';end if;
 b=asset.collision_bounds;l=new.x+(b->>'x')::numeric*new.scale;t=new.y+(b->>'y')::numeric*new.scale;w=(b->>'width')::numeric*new.scale;h=(b->>'height')::numeric*new.scale;
 if l<24 or t<24 or l+w>936 or t+h>616 or mod(new.x,24)<>0 or mod(new.y,24)<>0 then raise exception 'wall bounds or grid violation';end if;
 for other in select * from public.user_hobby_wall where user_id=new.user_id and id<>new.id loop
 select collision_bounds into ob from public.hobby_wall_items where id=other.item_id;
 if not(l+w+8<=other.x+(ob->>'x')::numeric*other.scale or other.x+((ob->>'x')::numeric+(ob->>'width')::numeric)*other.scale+8<=l or t+h+8<=other.y+(ob->>'y')::numeric*other.scale or other.y+((ob->>'y')::numeric+(ob->>'height')::numeric)*other.scale+8<=t) then raise exception 'wall collision';end if;
 end loop;return new;end $$;
create trigger wall_placement before insert or update on public.user_hobby_wall for each row execute function app_private.validate_wall();
create function public.save_hobby_wall(layout jsonb) returns void language plpgsql security invoker set search_path='' as $$
 declare entry jsonb; n integer=0; uid text=auth.uid();begin
 if uid is null then raise exception 'authentication required';end if;
 if jsonb_typeof(layout)<>'array' or jsonb_array_length(layout)>5 then raise exception 'maximum five wall items';end if;
 perform 1 from public.profiles where id=uid for update;
 delete from public.user_hobby_wall where user_id=uid;
 for entry in select * from jsonb_array_elements(layout) loop n=n+1;
 insert into public.user_hobby_wall(user_id,item_id,slot,x,y,scale,rotation,mount_type) values(uid,entry->>'itemId',n,(entry->>'x')::numeric,(entry->>'y')::numeric,coalesce((entry->>'scale')::numeric,1),coalesce((entry->>'rotation')::numeric,0),entry->>'mountType');end loop;end $$;
revoke all on function public.save_hobby_wall(jsonb) from public;
grant execute on function public.save_hobby_wall(jsonb) to authenticated;
